78	    /**
79	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
80	     * new owner's id, customer code and registration date.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys are the
86	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
87	     * expanded form it is replaced with.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
96	     * is at capacity and cannot take any more.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * The maximum number of owners that may be registered in a single day. Once this many owners
102	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
103	     * owners can be created that day.
104	     */
105	    private static final int DAILY_OWNER_LIMIT = 100;
106	
107	    /**
108	     * The number of owners that may be registered on a single business day before a response starts
109	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
110	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
111	     * high volume.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    /**
116	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
117	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
118	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
119	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
120	     */
121	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
122	        "61", 9,
123	        "1", 10);
124	
125	    /**
126	     * Fixed region-to-postcode-range lookup used to validate an owner's optional postcode against the
127	     * region derived from the owner's city ({@link Owner#getLocality()}). Each value is the inclusive
128	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
129	     * city whose region is not listed (locality {@code 'UNKNOWN'}) carries no range and accepts any
130	     * 4-digit postcode.
131	     */
132	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
133	        "NSW", new int[] {2000, 2099},
134	        "VIC", new int[] {3000, 3099},
135	        "QLD", new int[] {4000, 4099});
