157	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
158	        Collection<Owner> owners;
159	        if (lastName != null) {
160	            owners = this.clinicService.findOwnerByLastName(lastName);
161	        } else {
162	            owners = this.clinicService.findAllOwners();
163	        }
164	        if (owners.isEmpty()) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
168	    }
