182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
185	        validateRequiredFields(ownerFieldsDto);
186	        LocalDate registrationDate = toBusinessDay(
187	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
188	        rejectDailyLimitReached(registrationDate);
189	        HttpHeaders headers = new HttpHeaders();
190	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
191	        String address = normalizeAddress(ownerFieldsDto.getAddress());
192	        owner.setAddress(address);
193	        rejectCityAtCapacity(owner.getCity());
194	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
195	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
196	        }
197	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
198	        owner.setTelephone(telephone);
199	        String email = normalizeEmail(ownerFieldsDto.getEmail());
200	        owner.setEmail(email);
201	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), owner.getLocality()));
202	        rejectDuplicateIdentity(owner);
203	        owner.setRegistrationDate(registrationDate);
204	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
205	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
206	        this.clinicService.saveOwner(owner);
207	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
208	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        applyBulkSignupWarning(ownerDto);
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
214	    }
