310	    /**
311	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
312	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
313	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
314	     *
315	     * @param ownerFieldsDto the submitted owner fields
316	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
317	     *                                     name of every offending field
318	     */
319	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
320	        List<String> missingFields = new ArrayList<>();
321	        if (isBlank(ownerFieldsDto.getFirstName())) {
322	            missingFields.add("firstName");
323	        }
324	        if (isBlank(ownerFieldsDto.getLastName())) {
325	            missingFields.add("lastName");
326	        }
327	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
328	            missingFields.add("address");
329	        }
330	        if (isBlank(ownerFieldsDto.getCity())) {
331	            missingFields.add("city");
332	        }
333	        if (isBlank(ownerFieldsDto.getTelephone())) {
334	            missingFields.add("telephone");
335	        }
336	        if (!missingFields.isEmpty()) {
337	            throw new InvalidOwnerFieldsException(missingFields);
338	        }
339	    }
340	
341	    private boolean isBlank(String value) {
342	        return value == null || value.isBlank();
343	    }
344	
345	    /**
346	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
347	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
348	     * exactly 4 digits, and when the owner's region (derived from its city, {@link Owner#getLocality()})
349	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
350	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
351	     * The returned value is stored and returned unchanged.
352	     *
353	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
354	     * @param region   the owner's region derived from its city
355	     * @return the postcode to store, or {@code null} if none was supplied
356	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
357	     *                                     out of range for the city's region, yielding a 400 response
358	     */
359	    private String validatePostcode(String postcode, String region) {
360	        if (postcode == null) {
361	            return null;
362	        }
363	        if (!postcode.matches("[0-9]{4}")) {
364	            throw new InvalidOwnerFieldsException(List.of("postcode"));
365	        }
366	        int[] range = REGION_POSTCODES.get(region);
367	        if (range != null) {
368	            int value = Integer.parseInt(postcode);
369	            if (value < range[0] || value > range[1]) {
370	                throw new InvalidOwnerFieldsException(List.of("postcode"));
371	            }
372	        }
373	        return postcode;
374	    }
375	
376	    /**
377	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
378	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
379	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
380	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
381	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
382	     *
383	     * @param telephone the raw telephone value submitted by the client
384	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
385	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
386	     *                                     400 response
387	     */
388	    private String normalizeTelephone(String telephone) {
389	        String e164 = toE164(telephone);
390	        if (e164 == null) {
391	            throw new InvalidOwnerFieldsException(List.of("telephone"));
392	        }
393	        return e164;
394	    }
395	
396	    /**
397	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
398	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
399	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
400	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
401	     * and when the supplied country code is one with a known national-number length
402	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
403	     * number must have exactly that many digits.
404	     *
405	     * @param telephone the raw telephone value, possibly {@code null}
406	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
407	     */
408	    private String toE164(String telephone) {
409	        if (telephone == null) {
410	            return null;
411	        }
412	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
413	        boolean hasPlus = cleaned.startsWith("+");
414	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
415	        String nationalSignificant = hasPlus
416	            ? digits
417	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
418	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
419	            return null;
420	        }
421	        if (!hasValidNationalNumberLength(nationalSignificant)) {
422	            return null;
423	        }
424	        return "+" + nationalSignificant;
425	    }
426	
427	    /**
428	     * Checks the national-number length of an E.164 number (country code plus national significant
429	     * digits, no leading {@code '+'}) against the per-country requirement in
430	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
431	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
432	     * country code is not listed carries no per-country length requirement and is accepted.
433	     *
434	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
435	     *                            leading {@code '+'}
436	     * @return {@code true} if the national-number length is correct for the country code, or the
437	     *         country code has no listed requirement; {@code false} otherwise
438	     */
439	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
440	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
441	            .filter(nationalSignificant::startsWith)
442	            .max(Comparator.comparingInt(String::length))
443	            .orElse(null);
444	        if (countryCode == null) {
445	            return true;
446	        }
447	        int nationalLength = nationalSignificant.length() - countryCode.length();
448	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
449	    }
450	
451	    /**
452	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
453	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
454	     * returned value is that address lower-cased.
455	     *
456	     * @param email the raw email value submitted by the client, or {@code null} if omitted
457	     * @return the lower-cased email, or {@code null} if none was supplied
458	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
459	     *                                     yielding a 400 response
460	     */
461	    private String normalizeEmail(String email) {
462	        if (email == null) {
463	            return null;
464	        }
465	        if (!EMAIL_PATTERN.matcher(email).matches()) {
466	            throw new InvalidOwnerFieldsException(List.of("email"));
467	        }
468	        return email.toLowerCase(Locale.ROOT);
469	    }
470	
471	    /**
472	     * Counts the existing owners that, before this create, already share the given first name and
473	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
474	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
475	     * been saved yet, so it is never included in the count.
476	     *
477	     * @param firstName the first name of the owner being created
478	     * @param lastName  the last name of the owner being created
479	     * @return the number of existing owners sharing both names
480	     */
481	    private int countNamesakes(String firstName, String lastName) {
482	        String normalizedFirstName = normalizeForComparison(firstName);
483	        String normalizedLastName = normalizeForComparison(lastName);
484	        return (int) this.clinicService.findAllOwners().stream()
485	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
486	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
487	            .count();
488	    }
489	
490	    /**
491	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
492	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
493	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
494	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
495	     *
496	     * @param city     the owner's city
497	     * @param lastName the owner's last name
498	     * @return the formatted customer code
499	     */
500	    private String generateCustomerCode(String city, String lastName) {
501	        String city3 = first3Letters(city);
502	        String last3 = first3Letters(lastName);
503	        int sequence = countOwnersInCity(city) + 1;
504	        return String.format("%s-%s-%04d", city3, last3, sequence);
505	    }
506	
507	    /**
508	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
509	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
510	     *
511	     * @param value the value to abbreviate
512	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
513	     */
514	    private String first3Letters(String value) {
515	        String letters = value.replaceAll("[^\\p{L}]", "");
516	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
517	    }
518	
519	    /**
520	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
521	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
522	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
523	     * has not been saved yet, so it is never included in the count.
524	     *
525	     * @param city the city of the owner being created
526	     * @return the number of existing owners in that city
527	     */
528	    private int countOwnersInCity(String city) {
529	        String normalizedCity = normalizeForComparison(city);
530	        return (int) this.clinicService.findAllOwners().stream()
531	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
532	            .count();
533	    }
534	
535	    /**
536	     * Rejects creation of an owner whose city already contains the maximum number of owners
537	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
538	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
539	     *
540	     * @param city the city of the owner being created
541	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
542	     *                                      owners, yielding a 409 Conflict response
543	     */
544	    private void rejectCityAtCapacity(String city) {
545	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
546	            throw new OwnerCityAtCapacityException(city);
547	        }
548	    }
549	
550	    /**
551	     * Rejects creation of an owner once the given business day has already reached its daily quota
552	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
553	     * being that day — the adjusted business day the owner being created will carry — so the quota
554	     * applies per business day. The owner being created has not been saved yet, so it is never
555	     * included in the count.
556	     *
557	     * @param registrationDate the adjusted business-day registration date of the owner being created
558	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
559	     *                                         carry that registration date, yielding a
560	     *                                         429 Too Many Requests response
561	     */
562	    private void rejectDailyLimitReached(LocalDate registrationDate) {
563	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
564	            throw new DailyOwnerLimitReachedException(registrationDate);
565	        }
566	    }
567	
568	    /**
569	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
570	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
571	     *
572	     * @param registrationDate the business day to count owners for
573	     * @return the number of existing owners registered on that day
574	     */
575	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
576	        return this.clinicService.findAllOwners().stream()
577	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
578	            .count();
579	    }
580	
581	    /**
582	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
583	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
584	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
585	     * otherwise.
586	     *
587	     * @param ownerDto the owner response to flag
588	     */
589	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
590	        LocalDate today = toBusinessDay(LocalDate.now());
591	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
592	    }
593	
594	    /**
595	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
596	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
597	     * applies to the effective registration date whether it was supplied in the request or defaulted
598	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
599	     * feeds every value derived from it (such as the membership number's year segment and the daily
600	     * create-limit's per-day bucket).
601	     *
602	     * @param date the effective registration date, supplied or defaulted
603	     * @return the same date when it is a weekday, otherwise the next Monday
604	     */
605	    private LocalDate toBusinessDay(LocalDate date) {
606	        LocalDate adjusted = date;
607	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
608	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
609	            adjusted = adjusted.plusDays(1);
610	        }
611	        return adjusted;
612	    }
613	
614	    /**
615	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
616	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
617	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
618	     * separate telephone, email and household checks are all expressed through it. Because the
619	     * telephone is part of the key, two members of the same household (same {@code householdId})
620	     * with different telephones have different identity keys and are both allowed; only a whole-key
621	     * match is a duplicate. The owner being created already carries its normalized telephone,
622	     * email and (if any) household id, and existing owners store the same normalized forms, so the
623	     * keys are compared directly.
624	     *
625	     * @param owner the owner being created, with its telephone, email and household id already set
626	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
627	     *                                         yielding a 409 Conflict response
628	     */
629	    private void rejectDuplicateIdentity(Owner owner) {
630	        String identityKey = owner.getIdentityKey();
631	        boolean inUse = this.clinicService.findAllOwners().stream()
632	            .map(Owner::getIdentityKey)
633	            .anyMatch(identityKey::equals);
634	        if (inUse) {
635	            throw new DuplicateOwnerIdentityException(identityKey);
636	        }
637	    }
638	
639	    /**
640	     * Finds every existing owner belonging to the household identified by the given last name and
641	     * address — that is, the owners the {@code sharesHousehold} opt-in joins. Both the last name and
642	     * the address are compared case-insensitively with surrounding and internal whitespace collapsed,
643	     * so values that differ only in letter case or spacing still match. This definition of household
644	     * membership is used by {@link #assignHousehold}.
645	     *
646	     * @param lastName the last name of the owner being created
647	     * @param address  the address of the owner being created
648	     * @return the existing owners in that household, or an empty list if there are none
649	     */
650	    private List<Owner> findHouseholdMembers(String lastName, String address) {
651	        String normalizedLastName = normalizeForComparison(lastName);
652	        String normalizedAddress = normalizeAddress(address);
653	        return this.clinicService.findAllOwners().stream()
654	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
655	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
656	            .toList();
657	    }
658	
659	    /**
660	     * Enrolls a newly created owner into the household of any existing owner that shares its last
661	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
662	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
663	     * whitespace. When at least one such owner already exists, every member of the household — the
664	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
665	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
666	     * and address is created and back-filled onto the existing members. When no owner yet lives at
667	     * that address under the same last name no identifier is assigned and the owner is created alone.
668	     *
669	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
670	     * @param lastName the last name of the owner being created
671	     * @param address  the address of the owner being created
672	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
673	     */
674	    private String assignHousehold(Owner newOwner, String lastName, String address) {
675	        List<Owner> members = findHouseholdMembers(lastName, address);
676	        if (members.isEmpty()) {
677	            return null;
678	        }
679	        String householdId = members.stream()
680	            .map(Owner::getHouseholdId)
681	            .filter(existing -> existing != null && !existing.isBlank())
682	            .findFirst()
683	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
684	        for (Owner member : members) {
685	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
686	                member.setHouseholdId(householdId);
687	                this.clinicService.saveOwner(member);
688	            }
689	        }
690	        newOwner.setHouseholdId(householdId);
691	        return householdId;
692	    }
693	
694	    /**
695	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
696	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
697	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
698	     * same identifier, so members of one household share a single value.
699	     *
700	     * @param normalizedLastName the household's last name, already normalized for comparison
701	     * @param normalizedAddress  the household's address, already normalized for comparison
702	     * @return the derived household identifier
703	     */
704	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
705	        try {
706	            byte[] digest = MessageDigest.getInstance("SHA-256")
707	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
708	            StringBuilder hex = new StringBuilder(digest.length * 2);
709	            for (byte b : digest) {
710	                hex.append(String.format("%02x", b));
711	            }
712	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
713	        } catch (NoSuchAlgorithmException e) {
714	            throw new IllegalStateException("SHA-256 algorithm not available", e);
715	        }
716	    }
717	
718	    /**
719	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
720	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
721	     * the result is lower-cased.
722	     *
723	     * @param value the value to normalize, possibly {@code null}
724	     * @return the normalized value, or an empty string if {@code value} is {@code null}
725	     */
726	    private String normalizeForComparison(String value) {
727	        if (value == null) {
728	            return "";
729	        }
730	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
731	    }
732	
733	    /**
734	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
735	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
736	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
737	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
738	     * This normalized value is what gets stored and returned, and it is the form every address
739	     * comparison (household duplicate detection and the shared household id) uses.
740	     *
741	     * @param address the raw address value submitted by the client, possibly {@code null}
742	     * @return the normalized address, or an empty string if {@code address} is {@code null}
743	     */
744	    private String normalizeAddress(String address) {
745	        if (address == null) {
746	            return "";
747	        }
748	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
749	        if (collapsed.isEmpty()) {
750	            return collapsed;
751	        }
752	        String[] tokens = collapsed.split(" ");
753	        StringBuilder normalized = new StringBuilder(collapsed.length());
754	        for (int i = 0; i < tokens.length; i++) {
755	            if (i > 0) {
756	                normalized.append(' ');
757	            }
758	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
759	        }
760	        return normalized.toString();
761	    }
762	}
