66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    /**
73	     * Fixed city-to-region lookup backing {@link #getLocality()}. Used as the fallback when the
74	     * postcode is absent or in no known range. Any city not listed derives locality {@code 'UNKNOWN'}.
75	     */
76	    private static final Map<String, String> CITY_REGION = Map.of(
77	        "Sydney", "NSW",
78	        "Melbourne", "VIC",
79	        "Brisbane", "QLD");
80	
81	    /**
82	     * Fixed region-to-postcode-range lookup backing {@link #getLocality()}. Each value is the
83	     * inclusive {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099,
84	     * QLD 4000-4099). The postcode is preferred over the city when deriving the locality.
85	     */
86	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
87	        "NSW", new int[] {2000, 2099},
88	        "VIC", new int[] {3000, 3099},
89	        "QLD", new int[] {4000, 4099});
90	
91	    public String getAddress() {
92	        return this.address;
93	    }
94	
